CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. 320 chars is the RFC 5321 maximum for an address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown on a profile and next to a collaborative playlist edit.
	"display_name" VARCHAR(80) NOT NULL,
	-- ISO 3166-1 alpha-2. Licensing is territorial, so the account country decides which tracks are playable at all.
	"country_code" CHAR(2) NOT NULL,
	-- free | premium | family_member. Gates offline downloads and on-demand play of a full album.
	"product_tier" VARCHAR(20) NOT NULL DEFAULT 'free',
	-- Used for age-restricted content and ad targeting. Null when the signup flow did not ask.
	"birth_date" DATE,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A listening account. Country is stored on the account rather than derived from the request IP, because licensing has to survive the user travelling.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity. 320 chars is the RFC 5321 maximum for an address.';
COMMENT ON COLUMN "users"."display_name" IS 'Name shown on a profile and next to a collaborative playlist edit.';
COMMENT ON COLUMN "users"."country_code" IS 'ISO 3166-1 alpha-2. Licensing is territorial, so the account country decides which tracks are playable at all.';
COMMENT ON COLUMN "users"."product_tier" IS 'free | premium | family_member. Gates offline downloads and on-demand play of a full album.';
COMMENT ON COLUMN "users"."birth_date" IS 'Used for age-restricted content and ad targeting. Null when the signup flow did not ask.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE INDEX "idx_users_country"
ON "users" ("country_code");

CREATE TABLE IF NOT EXISTS "artists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Billed artist name. Not unique - there are several bands called Nirvana and the catalog has to hold all of them.
	"name" VARCHAR(200) NOT NULL,
	-- Name reordered for alphabetical browsing, e.g. "Beatles, The".
	"sort_name" VARCHAR(200) NOT NULL,
	-- Long-form biography shown on the artist page.
	"bio" TEXT,
	-- True when the artist has claimed the profile and can publish to it.
	"verified" BOOLEAN NOT NULL DEFAULT false,
	-- Rolling 28-day distinct-listener count, recomputed by a batch job. Denormalised because every artist page reads it.
	"monthly_listeners" INTEGER NOT NULL DEFAULT 0,
	-- When the artist first entered the catalog.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "artists" IS 'A credited musical act, band or performer. An artist is a catalog entity, not a user account; a musician who also listens has a separate users row.';
COMMENT ON COLUMN "artists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "artists"."name" IS 'Billed artist name. Not unique - there are several bands called Nirvana and the catalog has to hold all of them.';
COMMENT ON COLUMN "artists"."sort_name" IS 'Name reordered for alphabetical browsing, e.g. "Beatles, The".';
COMMENT ON COLUMN "artists"."bio" IS 'Long-form biography shown on the artist page.';
COMMENT ON COLUMN "artists"."verified" IS 'True when the artist has claimed the profile and can publish to it.';
COMMENT ON COLUMN "artists"."monthly_listeners" IS 'Rolling 28-day distinct-listener count, recomputed by a batch job. Denormalised because every artist page reads it.';
COMMENT ON COLUMN "artists"."created_at" IS 'When the artist first entered the catalog.';

CREATE INDEX "idx_artists_sort_name"
ON "artists" ("sort_name");

CREATE TABLE IF NOT EXISTS "albums" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The act the release is filed under. Individual tracks may credit entirely different people.
	"primary_artist_id" BIGINT NOT NULL,
	-- Release title as printed on the cover.
	"title" VARCHAR(300) NOT NULL,
	-- album | single | ep | compilation. Drives how the release is grouped on the artist page.
	"album_type" VARCHAR(20) NOT NULL DEFAULT 'album',
	-- Release date. A date, not a timestamp - a release belongs to a calendar day, and reissues carry the original day.
	"release_date" DATE,
	-- Universal Product Code from the label. The identifier rights holders and royalty reports agree on.
	"upc" VARCHAR(20) UNIQUE,
	-- Record label that delivered the release.
	"label" VARCHAR(160),
	-- Track count cached on the release so a listing does not have to count rows.
	"total_tracks" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "albums" IS 'A release. Every track belongs to exactly one release, so a song that appears on a single and later on an album is two track rows sharing an ISRC.';
COMMENT ON COLUMN "albums"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "albums"."primary_artist_id" IS 'The act the release is filed under. Individual tracks may credit entirely different people.';
COMMENT ON COLUMN "albums"."title" IS 'Release title as printed on the cover.';
COMMENT ON COLUMN "albums"."album_type" IS 'album | single | ep | compilation. Drives how the release is grouped on the artist page.';
COMMENT ON COLUMN "albums"."release_date" IS 'Release date. A date, not a timestamp - a release belongs to a calendar day, and reissues carry the original day.';
COMMENT ON COLUMN "albums"."upc" IS 'Universal Product Code from the label. The identifier rights holders and royalty reports agree on.';
COMMENT ON COLUMN "albums"."label" IS 'Record label that delivered the release.';
COMMENT ON COLUMN "albums"."total_tracks" IS 'Track count cached on the release so a listing does not have to count rows.';

CREATE INDEX "idx_albums_artist_release"
ON "albums" ("primary_artist_id", "release_date");

CREATE TABLE IF NOT EXISTS "tracks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Release this recording appears on.
	"album_id" BIGINT NOT NULL,
	-- Track title without the featured-artist suffix; credits come from track_artists.
	"title" VARCHAR(300) NOT NULL,
	-- Disc within a multi-disc release.
	"disc_number" SMALLINT NOT NULL DEFAULT 1,
	-- Position on the disc. Ordering within a release is fixed by the label, not by the listener.
	"track_number" SMALLINT NOT NULL,
	-- Runtime in milliseconds. Integer milliseconds avoid the rounding drift that float seconds introduce in scrubbing UI.
	"duration_ms" INTEGER NOT NULL,
	-- International Standard Recording Code. The same recording licensed to several releases shares one ISRC, which is how royalties are matched.
	"isrc" CHAR(12),
	-- Parental advisory flag, filtered out for accounts with explicit content disabled.
	"explicit" BOOLEAN NOT NULL DEFAULT false,
	-- False when the recording has been pulled from streaming but must stay visible in old playlists as a greyed-out row.
	"is_playable" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "tracks" IS 'One recording on one release. Tracks are never hard-deleted: a takedown flips is_playable, because deleting the row would silently rewrite every playlist that contained it.';
COMMENT ON COLUMN "tracks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "tracks"."album_id" IS 'Release this recording appears on.';
COMMENT ON COLUMN "tracks"."title" IS 'Track title without the featured-artist suffix; credits come from track_artists.';
COMMENT ON COLUMN "tracks"."disc_number" IS 'Disc within a multi-disc release.';
COMMENT ON COLUMN "tracks"."track_number" IS 'Position on the disc. Ordering within a release is fixed by the label, not by the listener.';
COMMENT ON COLUMN "tracks"."duration_ms" IS 'Runtime in milliseconds. Integer milliseconds avoid the rounding drift that float seconds introduce in scrubbing UI.';
COMMENT ON COLUMN "tracks"."isrc" IS 'International Standard Recording Code. The same recording licensed to several releases shares one ISRC, which is how royalties are matched.';
COMMENT ON COLUMN "tracks"."explicit" IS 'Parental advisory flag, filtered out for accounts with explicit content disabled.';
COMMENT ON COLUMN "tracks"."is_playable" IS 'False when the recording has been pulled from streaming but must stay visible in old playlists as a greyed-out row.';

CREATE UNIQUE INDEX "uq_tracks_album_position"
ON "tracks" ("album_id", "disc_number", "track_number");
CREATE INDEX "idx_tracks_isrc"
ON "tracks" ("isrc");

CREATE TABLE IF NOT EXISTS "track_artists" (
	-- Recording being credited.
	"track_id" BIGINT,
	-- Artist receiving the credit.
	"artist_id" BIGINT,
	-- primary | featured | remixer | composer | producer. Part of the key, because one person can be both composer and performer on the same track.
	"role" VARCHAR(24),
	-- Order within the role, so "A, B & C" renders in the billing order the label specified.
	"position" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("track_id", "artist_id", "role")
);

COMMENT ON TABLE "track_artists" IS 'The credits join table. Carrying the role in the primary key is what lets a track have several featured artists and a separate composer without duplicating rows or inventing a credits blob.';
COMMENT ON COLUMN "track_artists"."track_id" IS 'Recording being credited.';
COMMENT ON COLUMN "track_artists"."artist_id" IS 'Artist receiving the credit.';
COMMENT ON COLUMN "track_artists"."role" IS 'primary | featured | remixer | composer | producer. Part of the key, because one person can be both composer and performer on the same track.';
COMMENT ON COLUMN "track_artists"."position" IS 'Order within the role, so "A, B & C" renders in the billing order the label specified.';

CREATE INDEX "idx_track_artists_artist_role"
ON "track_artists" ("artist_id", "role");

CREATE TABLE IF NOT EXISTS "playlists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account that created the playlist and controls its settings.
	"owner_id" BIGINT NOT NULL,
	-- Playlist title as typed by the owner.
	"name" VARCHAR(120) NOT NULL,
	-- Optional blurb shown under the title.
	"description" VARCHAR(500),
	-- Whether the playlist appears on the owner profile and can be opened by link.
	"is_public" BOOLEAN NOT NULL DEFAULT true,
	-- When true, rows in playlist_collaborators may add and remove items.
	"is_collaborative" BOOLEAN NOT NULL DEFAULT false,
	-- Opaque version token bumped on every mutation. Clients send it back on edits so a stale offline device cannot reorder a playlist someone else has since changed.
	"snapshot_id" VARCHAR(64) NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last content or metadata change; drives "recently updated" sorting.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "playlists" IS 'A user-curated list. Editorial playlists live here too, owned by a house account, so the player needs no second code path for them.';
COMMENT ON COLUMN "playlists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "playlists"."owner_id" IS 'Account that created the playlist and controls its settings.';
COMMENT ON COLUMN "playlists"."name" IS 'Playlist title as typed by the owner.';
COMMENT ON COLUMN "playlists"."description" IS 'Optional blurb shown under the title.';
COMMENT ON COLUMN "playlists"."is_public" IS 'Whether the playlist appears on the owner profile and can be opened by link.';
COMMENT ON COLUMN "playlists"."is_collaborative" IS 'When true, rows in playlist_collaborators may add and remove items.';
COMMENT ON COLUMN "playlists"."snapshot_id" IS 'Opaque version token bumped on every mutation. Clients send it back on edits so a stale offline device cannot reorder a playlist someone else has since changed.';
COMMENT ON COLUMN "playlists"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "playlists"."updated_at" IS 'Last content or metadata change; drives "recently updated" sorting.';

CREATE INDEX "idx_playlists_owner_updated"
ON "playlists" ("owner_id", "updated_at");

CREATE TABLE IF NOT EXISTS "playlist_items" (
	-- Surrogate primary key. Deliberately not (playlist_id, track_id): the same track may legitimately appear twice in one playlist.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent playlist.
	"playlist_id" BIGINT NOT NULL,
	-- Recording placed in the list.
	"track_id" BIGINT NOT NULL,
	-- Zero-based slot. Reordering rewrites the affected positions in one transaction rather than shuffling a linked list.
	"position" INTEGER NOT NULL,
	-- Collaborator who added the item. Null for items added before collaboration existed or by an imported playlist.
	"added_by_id" BIGINT,
	-- When the track entered the playlist; shown in the collaborative view and used for "added recently" sorting.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "playlist_items" IS 'Ordered playlist membership. Position is an explicit integer column because a playlist is a sequence, and any ordering derived from added_at breaks the first time someone drags a row.';
COMMENT ON COLUMN "playlist_items"."id" IS 'Surrogate primary key. Deliberately not (playlist_id, track_id): the same track may legitimately appear twice in one playlist.';
COMMENT ON COLUMN "playlist_items"."playlist_id" IS 'Parent playlist.';
COMMENT ON COLUMN "playlist_items"."track_id" IS 'Recording placed in the list.';
COMMENT ON COLUMN "playlist_items"."position" IS 'Zero-based slot. Reordering rewrites the affected positions in one transaction rather than shuffling a linked list.';
COMMENT ON COLUMN "playlist_items"."added_by_id" IS 'Collaborator who added the item. Null for items added before collaboration existed or by an imported playlist.';
COMMENT ON COLUMN "playlist_items"."added_at" IS 'When the track entered the playlist; shown in the collaborative view and used for "added recently" sorting.';

CREATE UNIQUE INDEX "uq_playlist_items_position"
ON "playlist_items" ("playlist_id", "position");
CREATE INDEX "idx_playlist_items_track"
ON "playlist_items" ("track_id");

CREATE TABLE IF NOT EXISTS "playlist_collaborators" (
	-- Playlist being shared.
	"playlist_id" BIGINT,
	-- Account granted edit rights.
	"user_id" BIGINT,
	-- Whether the collaborator may move items or only append them.
	"can_reorder" BOOLEAN NOT NULL DEFAULT true,
	-- When access was granted; an accepted-invite audit trail without a separate invites table.
	"invited_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("playlist_id", "user_id")
);

COMMENT ON TABLE "playlist_collaborators" IS 'Edit rights on a collaborative playlist. The owner is intentionally absent from this table - ownership lives on playlists.owner_id and cannot be revoked here.';
COMMENT ON COLUMN "playlist_collaborators"."playlist_id" IS 'Playlist being shared.';
COMMENT ON COLUMN "playlist_collaborators"."user_id" IS 'Account granted edit rights.';
COMMENT ON COLUMN "playlist_collaborators"."can_reorder" IS 'Whether the collaborator may move items or only append them.';
COMMENT ON COLUMN "playlist_collaborators"."invited_at" IS 'When access was granted; an accepted-invite audit trail without a separate invites table.';

CREATE TABLE IF NOT EXISTS "follows" (
	-- Surrogate primary key. A composite key is impossible here because one of the two target columns is always null.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account doing the following.
	"follower_id" BIGINT NOT NULL,
	-- Artist being followed. Null when this row is a user-to-user follow.
	"artist_id" BIGINT,
	-- User being followed. Null when this row is an artist follow. Exactly one of artist_id and followee_id is set, enforced by a check constraint.
	"followee_id" BIGINT,
	-- When the follow happened; new-release notifications only cover releases after this point.
	"followed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "follows" IS 'Follows for both artists and other listeners in one table, because the notification fan-out treats them identically. The two partial unique indexes stop a duplicate follow of either kind.';
COMMENT ON COLUMN "follows"."id" IS 'Surrogate primary key. A composite key is impossible here because one of the two target columns is always null.';
COMMENT ON COLUMN "follows"."follower_id" IS 'Account doing the following.';
COMMENT ON COLUMN "follows"."artist_id" IS 'Artist being followed. Null when this row is a user-to-user follow.';
COMMENT ON COLUMN "follows"."followee_id" IS 'User being followed. Null when this row is an artist follow. Exactly one of artist_id and followee_id is set, enforced by a check constraint.';
COMMENT ON COLUMN "follows"."followed_at" IS 'When the follow happened; new-release notifications only cover releases after this point.';

CREATE UNIQUE INDEX "uq_follows_artist"
ON "follows" ("follower_id", "artist_id");
CREATE UNIQUE INDEX "uq_follows_user"
ON "follows" ("follower_id", "followee_id");

CREATE TABLE IF NOT EXISTS "library_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the library.
	"user_id" BIGINT NOT NULL,
	-- track | album | playlist. Says which of the three id columns below is populated.
	"item_type" VARCHAR(16) NOT NULL,
	-- Saved track, when item_type is track.
	"track_id" BIGINT,
	-- Saved album, when item_type is album.
	"album_id" BIGINT,
	-- Saved playlist, when item_type is playlist. A save is not a copy: the playlist keeps changing under the saver.
	"playlist_id" BIGINT,
	-- When the item was saved. Library sorting is almost always by this column, not by title.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "library_items" IS 'Saved Your Library rows for three different things. Three nullable foreign keys keep referential integrity, which a single polymorphic (item_type, item_id) pair would throw away.';
COMMENT ON COLUMN "library_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "library_items"."user_id" IS 'Owner of the library.';
COMMENT ON COLUMN "library_items"."item_type" IS 'track | album | playlist. Says which of the three id columns below is populated.';
COMMENT ON COLUMN "library_items"."track_id" IS 'Saved track, when item_type is track.';
COMMENT ON COLUMN "library_items"."album_id" IS 'Saved album, when item_type is album.';
COMMENT ON COLUMN "library_items"."playlist_id" IS 'Saved playlist, when item_type is playlist. A save is not a copy: the playlist keeps changing under the saver.';
COMMENT ON COLUMN "library_items"."added_at" IS 'When the item was saved. Library sorting is almost always by this column, not by title.';

CREATE INDEX "idx_library_user_added"
ON "library_items" ("user_id", "added_at");
CREATE UNIQUE INDEX "uq_library_user_track"
ON "library_items" ("user_id", "track_id");
CREATE UNIQUE INDEX "uq_library_user_album"
ON "library_items" ("user_id", "album_id");

CREATE TABLE IF NOT EXISTS "play_events" (
	-- Surrogate primary key. Monotonic, so the log can be paged by id without a stable-sort tiebreaker.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Listener.
	"user_id" BIGINT NOT NULL,
	-- Recording played.
	"track_id" BIGINT NOT NULL,
	-- Start of playback. The partition key in practice - this table is range-partitioned by month.
	"played_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Milliseconds actually heard. Royalty payouts only count a play above a threshold, so the duration has to be recorded, not inferred.
	"ms_played" INTEGER NOT NULL,
	-- album | playlist | artist | radio | search. What the listener was playing from, which is how recommendation quality is measured.
	"context_type" VARCHAR(20),
	-- Id of that context. Deliberately unconstrained: the log must not hold a foreign key that blocks deleting a playlist.
	"context_id" BIGINT,
	-- phone | desktop | speaker | car. Null when the client did not report it.
	"device_type" VARCHAR(24),
	-- True when the next track was requested before the end. A skip is the strongest negative signal the recommender has.
	"skipped" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "play_events" IS 'Append-only listening log: one row per play, never updated, never deleted in place. Play counts, Wrapped, royalties and recommendations are all rollups of this table.';
COMMENT ON COLUMN "play_events"."id" IS 'Surrogate primary key. Monotonic, so the log can be paged by id without a stable-sort tiebreaker.';
COMMENT ON COLUMN "play_events"."user_id" IS 'Listener.';
COMMENT ON COLUMN "play_events"."track_id" IS 'Recording played.';
COMMENT ON COLUMN "play_events"."played_at" IS 'Start of playback. The partition key in practice - this table is range-partitioned by month.';
COMMENT ON COLUMN "play_events"."ms_played" IS 'Milliseconds actually heard. Royalty payouts only count a play above a threshold, so the duration has to be recorded, not inferred.';
COMMENT ON COLUMN "play_events"."context_type" IS 'album | playlist | artist | radio | search. What the listener was playing from, which is how recommendation quality is measured.';
COMMENT ON COLUMN "play_events"."context_id" IS 'Id of that context. Deliberately unconstrained: the log must not hold a foreign key that blocks deleting a playlist.';
COMMENT ON COLUMN "play_events"."device_type" IS 'phone | desktop | speaker | car. Null when the client did not report it.';
COMMENT ON COLUMN "play_events"."skipped" IS 'True when the next track was requested before the end. A skip is the strongest negative signal the recommender has.';

CREATE INDEX "idx_play_events_user_time"
ON "play_events" ("user_id", "played_at");
CREATE INDEX "idx_play_events_track_time"
ON "play_events" ("track_id", "played_at");

CREATE TABLE IF NOT EXISTS "downloads" (
	-- Account that downloaded for offline use.
	"user_id" BIGINT,
	-- Recording cached on the device.
	"track_id" BIGINT,
	-- Stable client-generated device identifier. Part of the key because the same track downloaded on a phone and a laptop are two independent caches with separate licences.
	"device_id" VARCHAR(64),
	-- Encrypted file size on disk, used for the storage meter in settings.
	"bytes" INTEGER NOT NULL,
	-- low | normal | high | very_high. Bitrate ladder rung chosen for the cached file.
	"quality" VARCHAR(16) NOT NULL DEFAULT 'normal',
	-- When the cache was written.
	"downloaded_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the offline licence lapses if the device never reconnects. Storing the expiry rather than a days-remaining counter means a clock change cannot extend it.
	"license_expires_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("user_id", "track_id", "device_id")
);

COMMENT ON TABLE "downloads" IS 'Offline cache bookkeeping, one row per track per device. Premium-only, and the licence expiry is what makes an unsubscribed account stop playing downloads without the server having to reach the device.';
COMMENT ON COLUMN "downloads"."user_id" IS 'Account that downloaded for offline use.';
COMMENT ON COLUMN "downloads"."track_id" IS 'Recording cached on the device.';
COMMENT ON COLUMN "downloads"."device_id" IS 'Stable client-generated device identifier. Part of the key because the same track downloaded on a phone and a laptop are two independent caches with separate licences.';
COMMENT ON COLUMN "downloads"."bytes" IS 'Encrypted file size on disk, used for the storage meter in settings.';
COMMENT ON COLUMN "downloads"."quality" IS 'low | normal | high | very_high. Bitrate ladder rung chosen for the cached file.';
COMMENT ON COLUMN "downloads"."downloaded_at" IS 'When the cache was written.';
COMMENT ON COLUMN "downloads"."license_expires_at" IS 'When the offline licence lapses if the device never reconnects. Storing the expiry rather than a days-remaining counter means a clock change cannot extend it.';

CREATE INDEX "idx_downloads_user_device"
ON "downloads" ("user_id", "device_id");

